function soloShell(body,{decision=false,conversation=false,complete=false,visual=true}={}){let cls=decision?'solo-decision':conversation?'solo-conversation':complete?'solo-complete':'';let phase=soloState?.phase||'meet';layout(`${soloNav()}<div class="solo-utility"><b>SINGLE PLAYER</b><button type="button" id="soloRestart">START OVER</button></div>${visual?visualBand(phase):''}<main class="solo-game ${cls}">${body}</main>`);q('#soloRestart').onclick=()=>{if(confirm('Start Arthur’s journey again?'))soloReset()};if(q('#soloBack'))q('#soloBack').onclick=()=>soloBack()}
