function soloCost(id){return costs[id]||[0,0]}
function soloMeet(){soloShell(`<section class="arthur-hero branded-intro"><img src="${asset('arthur-intro.png')}" alt="Arthur preparing to leave the hospital"><div class="brandline"><span>ARTHUR: BY DESIGN</span><strong>STANTEC</strong></div><div class="arthur-hero-copy"><div class="eyebrow">MEET ARTHUR</div><h1>ARTHUR IS<br>GOING HOME.</h1><p class="solo-lead intro-short">Cardiac surgery is behind Arthur.<br><b>The harder part may be what comes next.</b></p>${soloButton('soloNext','FOLLOW ARTHUR →',()=>soloGo('journey'))}</div></section>`,{visual:false})}
function soloJourney(){soloShell(`<section class="journey-editorial"><div class="journey-brand"><span>ARTHUR: BY DESIGN</span><strong>STANTEC</strong></div><h1>A JOURNEY OF CARE.<br>A LIFETIME OF POSSIBILITY.</h1><p class="journey-intro">Arthur moves through three connected environments. What you design today can shape what’s possible tomorrow.</p><div class="journey-visual-grid journey-select-grid"><button type="button" class="journey-path" data-path="leave"><img src="${asset('arthur-leave-well.png')}" alt="Hospital to home"><span class="journey-icon">↗</span><span class="journey-path-copy"><b>LEAVE WELL</b><strong>Hospital → Home</strong><small>Can Arthur understand the plan, navigate the transition and arrive home with confidence?</small></span></button><button type="button" class="journey-path" data-path="recover"><img src="${asset('arthur-recover-well.png')}" alt="Recovery at home"><span class="journey-icon">⌂</span><span class="journey-path-copy"><b>RECOVER WELL</b><strong>At Home</strong><small>Can Arthur recover safely, recognize change and get the right help when needed?</small></span></button><button type="button" class="journey-path" data-path="live"><img src="${asset('arthur-live-well.png')}" alt="Return to community life"><span class="journey-icon">◎</span><span class="journey-path-copy"><b>LIVE WELL</b><strong>In the Community</strong><small>Can Arthur regain independence, reconnect and participate in everyday life?</small></span></button></div><div class="journey-focus" id="journeyFocus"><b>TODAY WE BEGIN HERE: LEAVE WELL</b></div></section>`,{visual:false});let paths=document.querySelectorAll('.journey-path');paths.forEach(btn=>btn.onclick=()=>{paths.forEach(x=>x.classList.remove('selected'));btn.classList.add('selected');let path=btn.dataset.path;if(path==='leave'){soloGo('needs');return}let label=path==='recover'?'RECOVER WELL':'LIVE WELL',f=q('#journeyFocus');if(f)f.innerHTML=`<b>${label}</b><span>COMING NEXT · LEAVE WELL IS ACTIVE</span>`})}
function arthurKey(active=[]){let items=[['UNDERSTAND','?'],['MOVE','→'],['CONNECT','∞'],['TRUST','✓']];return `<div class="arthur-key"><strong>WHAT MATTERS TO ARTHUR</strong>${items.map(([n,g])=>`<span class="${active.length&&!active.includes(n)?'muted':''}"><i>${g}</i>${n}</span>`).join('')}</div>`}
const playerCapabilityNames={ambient:'SMART DISCHARGE',wayfinding:'SMART ROUTES',meds:'MEDICATION CHECK',command:'COORDINATED RESPONSE'};
const playerCapabilityLines={ambient:'AI turns the discharge conversation into a plan Arthur can take home.',wayfinding:'Directions adjust when Arthur’s path through the hospital changes.',meds:'AI checks medications and changes before Arthur leaves.',command:'People and information coordinate when Arthur’s transition changes.'};
const playerCapabilityWhat={ambient:'Creates one take-home plan.',wayfinding:'Updates Arthur’s route.',meds:'Finds medication conflicts before departure.',command:'Makes transition issues visible across the team.'};
const playerCapabilityWhy={ambient:'Arthur knows what changed and what comes next.',wayfinding:'Arthur can keep moving when the expected path changes.',meds:'Arthur leaves with one medication story.',command:'Arthur gets a coordinated response instead of fragmented answers.'};
const playerCapabilityDesign={ambient:'Give Arthur privacy and a place to review the plan before leaving.',wayfinding:'Digital directions need physical cues at real decision points.',meds:'Create a clear place to review, confirm and correct medications.',command:'Put coordination where teams can see and act on transition problems.'};
const playerCapabilityOperate={ambient:'Someone must confirm and own the plan.',wayfinding:'Someone must keep digital and physical guidance synchronized.',meds:'Someone must own medication changes across the handoff.',command:'Someone must have authority and capacity to respond.'};
function playerName(id){return playerCapabilityNames[id]||soloCapability(id)?.name||id}
function capabilityNeedTags(id){return `<div class="need-card-tags">${(needMap[id]||[]).map(n=>`<span>${n==='UNDERSTAND'?'?':n==='MOVE'?'→':n==='CONNECT'?'∞':'✓'} ${n}</span>`).join('')}</div>`}

function learnMoreDetails(id){return `<details class="learn-more"><summary>LEARN MORE</summary><div class="learn-more-grid"><section><b>FOR ARTHUR</b><p>${E(playerCapabilityWhy[id])}</p></section><section><b>DESIGN CONSIDERATION</b><p>${E(playerCapabilityDesign[id])}</p></section><section><b>TO MAKE IT WORK</b><p>${E(playerCapabilityOperate[id])}</p></section></div></details>`}

function soloNeeds(){soloShell(`<div class="eyebrow">LEAVE WELL · THE CHALLENGE</div><h1>FOUR THINGS MATTER.</h1>${arthurKey()}<div class="solo-needs"><div><b>UNDERSTAND</b><span>Does Arthur know what happened, what changed and what comes next?</span></div><div><b>MOVE</b><span>Can Arthur move safely and confidently from hospital to home?</span></div><div><b>CONNECT</b><span>Can Arthur stay connected to medications, people and follow-up?</span></div><div><b>TRUST</b><span>Does Arthur trust what to do next and who will respond?</span></div></div><div class="challenge-brief compact-brief"><b>YOUR CHALLENGE</b><span>Design an environment that helps Arthur leave well.</span></div>${soloButton('soloNext','SHOW ME HOW →',()=>soloGo('rules'))}`)}
function soloRules(){soloShell(`<div class="eyebrow">HOW THE GAME WORKS</div><h1>DESIGN FOR ARTHUR’S JOURNEY.</h1><div class="game-loop compact-loop"><article><span>◉</span><b>CHOOSE</b><small>Invest in AI-powered options.</small></article><article><span>◇</span><b>DESIGN</b><small>Make it work here.</small></article><article><span>↗</span><b>ADAPT</b><small>Strengthen or extend.</small></article><article><span>⚡</span><b>RESPOND</b><small>Conditions change.</small></article></div>${arthurKey()}<div class="resource-row"><strong>YOUR RESOURCES</strong><span class="resource-chip"><i>◆</i> 7 CAPITAL</span><span class="resource-chip"><i>●</i> 6 CHANGE</span><span class="resource-note">Capital funds what you build. Change is the capacity to implement it. Invest in up to 2 AI-powered options.</span></div>${soloButton('soloNext','UNDERSTAND YOUR INVESTMENT OPTIONS →',()=>soloGo('card-guide'))}`)}
function capabilityPreviewCards(){return S().capabilities.map(c=>{let [ca,ch]=soloCost(c.id);return `<article class="visual-cap-preview"><img src="${asset(leaveWellVisuals[c.id])}" alt="${E(playerName(c.id))}"><div class="visual-cap-copy"><div class="resource-mini"><span><i>◆</i> ${ca}</span><span><i>●</i> ${ch}</span></div><h2>${E(playerName(c.id))}</h2><small class="technical-name">${E(c.name)}</small><p>${E(playerCapabilityLines[c.id])}</p>${capabilityNeedTags(c.id)}</div></article>`}).join('')}

function soloCapabilityIntro(){soloShell(`<div class="eyebrow">STEP 1 OF 4 · DESIGN CAPABILITY</div><h1>CHOOSE HOW THE ENVIRONMENT SHOULD SUPPORT ARTHUR.</h1>${arthurKey()}<p class="solo-lead">Choose the AI-powered options that best support Arthur.</p><div class="capability-preview">${capabilityPreviewCards()}</div><div class="callout"><b>DESIGN CAPABILITIES</b> connect technology, the built environment and operating commitments to Arthur’s experience.</div>${soloButton('soloNext','CHOOSE YOUR INVESTMENT →',()=>soloGo('capability'))}`)}
function soloCardGuide(){let c=soloCapability('ambient'),[ca,ch]=soloCost(c.id);soloShell(`<div class="eyebrow">BEFORE YOU INVEST</div><h1>UNDERSTANDING YOUR INVESTMENT OPTIONS.</h1><p class="investment-teach"><b>Technology creates the capability.</b> Design determines Arthur’s experience.</p>${arthurKey(needMap[c.id])}<article class="learning-card visual-learning"><div class="learning-media"><img src="${asset(leaveWellVisuals[c.id])}" alt="Smart discharge"><div>${capabilityNeedTags(c.id)}</div></div><div class="learning-content"><div class="learning-title"><div><span class="eyebrow">EXAMPLE INVESTMENT OPTION</span><h2>${playerName(c.id)}</h2><small>${E(playerCapabilityLines[c.id])}</small></div><div class="resource-mini"><span><i>◆</i> ${ca}</span><span><i>●</i> ${ch}</span></div></div><div class="learning-points"><section><b>WHAT IT DOES</b><p>${E(playerCapabilityWhat[c.id])}</p></section><section><b>WHY ARTHUR CARES</b><p>${E(playerCapabilityWhy[c.id])}</p></section><section><b>TO MAKE IT WORK</b><p>${E(playerCapabilityOperate[c.id])}</p></section></div><div class="design-focus"><b>DESIGN CONSIDERATION</b><p>${E(playerCapabilityDesign[c.id])}</p></div></div></article>${soloButton('soloNext','SEE YOUR INVESTMENT OPTIONS →',()=>soloGo('capability-intro'))}`,{visual:false})}

function soloBars(){return`<div class="bars"><div><b>CAPITAL</b><span>${'●'.repeat(soloState.capital)}${'○'.repeat(7-soloState.capital)}</span><strong>${soloState.capital}</strong></div><div><b>CHANGE</b><span>${'●'.repeat(soloState.change)}${'○'.repeat(6-soloState.change)}</span><strong>${soloState.change}</strong></div></div>`}
function soloCapabilities(){let used=soloState.activations.map(a=>a.capabilityId),defs={ambient:'AI captures the discharge conversation and turns it into a clear transition plan that can follow Arthur from hospital to home.',wayfinding:'Digital guidance updates Arthur’s route as hospital destinations, access or conditions change.',meds:'AI compares medication information across the care journey to expose discrepancies before Arthur leaves.',command:'A connected operating capability makes constraints across Arthur’s transition visible and helps coordinate responses across departments.'},cards=S().capabilities.filter(c=>!used.includes(c.id)).map(c=>{let[ca,ch]=soloCost(c.id),disabled=ca>soloState.capital||ch>soloState.change,afterC=soloState.capital-ca,afterCh=soloState.change-ch;return`<article class="capability-primary ${disabled?'disabled':''}"><div class="capability-image cap-${c.id}"><img src="${asset(leaveWellVisuals[c.id])}" alt="${E(playerName(c.id))} in Arthur’s care journey"></div><div class="capability-heading"><div><div class="eyebrow">AI-POWERED OPTION</div><h2>${E(playerName(c.id))}</h2><small class="technical-name">${E(c.name)}</small></div><strong>${ca} CAPITAL · ${ch} CHANGE</strong></div><section class="what-it-is"><b>WHAT IT IS</b><p>${E(defs[c.id])}</p></section><section class="arthur-change"><b>WHAT IT COULD CHANGE FOR ARTHUR</b><h3>${E(soloFuture[c.id])}</h3></section><div class="tech-design"><p><b>TECHNOLOGY CAN</b><br>${E(playerCapabilityLines[c.id]||c.purpose)}</p><p><b>DESIGN STILL HAS TO</b><br>${E(soloWatch[c.id])}</p></div><div class="capacity-support">If activated: <b>${afterC} Capital · ${afterCh} Change remain.</b></div><details><summary>More detail</summary><p><b>BUILT ENVIRONMENT</b><br>${E(capabilityLong(c)?.environment||'The environment must support the experience.')}</p><p><b>PEOPLE + OPERATIONS</b><br>${E(capabilityLong(c)?.operations||'Workflow and ownership must be explicit.')}</p></details><button type="button" data-solo-cap="${c.id}" ${disabled?'disabled':''}>${disabled?'NOT ENOUGH CAPACITY':'INVEST IN THIS OPTION'}</button></article>`}).join('');soloShell(`${soloBars()}<div class="eyebrow">ARTHUR IS READY TO LEAVE THIS AFTERNOON</div><h1>WHAT WILL YOU INVEST FIRST?</h1><p class="solo-lead">Start with what each capability is and what it could change for Arthur. Cost and capacity support the decision; Arthur’s journey is the reason for it.</p><div class="solo-choice-list">${cards}</div>`,{decision:true});document.querySelectorAll('[data-solo-cap]').forEach(b=>b.onclick=()=>{soloState.pendingCapability=b.dataset.soloCap;saveSolo();soloSet('activation-impact')})}
const soloOperations={ambient:[{id:'protect',label:'Protect scheduled transition capacity',benefit:'Arthur gets a reliable time and setting for the discharge conversation.',tradeoff:'Protected capacity cannot be used freely for other demands.',dependency:'Scheduling ownership and protected time must hold when the hospital gets busy.',effect:-1,aha:'A designed place becomes dependable only when operating capacity is protected.'},{id:'flex',label:'Keep the setting flexible and shared',benefit:'The hospital preserves flexibility for other uses.',tradeoff:'Arthur’s conversation can be displaced when demand rises.',dependency:'The team needs a fallback when the preferred setting is unavailable.',effect:1,aha:'Flexible space is not the same as reliable care capacity.'},{id:'priority',label:'Prioritize discharge when demand rises',benefit:'Arthur’s transition receives explicit priority at critical times.',tradeoff:'Other work may wait or be rerouted.',dependency:'Priority rules and escalation ownership must be explicit.',effect:0,aha:'Priority is an operating choice, not a feature of the room.'}],wayfinding:[{id:'unit',label:'Give the unit ownership of route updates',benefit:'The team closest to Arthur can react quickly to local changes.',tradeoff:'The unit may not see system-wide route changes soon enough.',dependency:'Local staff need current route information and authority to update cues.',effect:0,aha:'Layered guidance is resilient only when someone owns synchronization.'},{id:'facilities',label:'Give Facilities / Wayfinding ownership',benefit:'Physical cues and route standards can be managed consistently.',tradeoff:'Updates may not match the speed of a clinical transition.',dependency:'A rapid update workflow must connect operational change to physical cues.',effect:-1,aha:'Physical adaptability has a response time.'},{id:'command',label:'Coordinate updates through the command center',benefit:'Route, capacity and cross-department changes can be coordinated from one view.',tradeoff:'The model depends on command authority and available responders.',dependency:'Digital, physical and human channels must receive the same change.',effect:-1,aha:'Coordination adds value only when it can change the environment in time.'}],meds:[{id:'nurse',label:'Protect nurse resolution time',benefit:'The clinician closest to Arthur can resolve and explain discrepancies.',tradeoff:'Protected time competes with discharge and unit demands.',dependency:'Coverage must absorb other tasks while medication issues are resolved.',effect:0,aha:'Ownership without protected capacity is fragile.'},{id:'pharmacy',label:'Guarantee pharmacy response coverage',benefit:'Specialist review remains available during transition.',tradeoff:'Arthur’s flow depends on a cross-department service level.',dependency:'Response times and escalation must be explicit.',effect:0,aha:'A specialist workflow becomes part of discharge design.'},{id:'huddle',label:'Protect a transition huddle',benefit:'Medication, discharge and movement decisions are reconciled together.',tradeoff:'Several people must be available at the same time.',dependency:'The hospital must protect shared transition time.',effect:-1,aha:'Integration requires operating capacity, not just connected data.'}],command:[{id:'existing',label:'Coordinate existing resources',benefit:'The hospital uses visibility to redirect what is already available.',tradeoff:'There may be nothing available to redirect at the critical moment.',dependency:'Authority helps only when people, routes or space can actually move.',effect:1,aha:'Visibility does not create capacity.'},{id:'protect',label:'Protect transition capacity',benefit:'People, routes or spaces remain available for transitions like Arthur’s.',tradeoff:'Protected capacity reduces flexibility for other demands.',dependency:'The hospital must decide what capacity is worth defending.',effect:-1,aha:'Resilience often comes from capacity designed before disruption.'},{id:'flex',label:'Maintain flexible response capacity',benefit:'The system can redeploy support as disruptions emerge.',tradeoff:'Flex capacity carries ongoing staffing and operating cost.',dependency:'Roles, authority and triggers for redeployment must be clear.',effect:-1,aha:'Flexibility is an operating capability that must be funded and designed.'}]};
function capabilityAha(id){return{ambient:'Technology can create the transition plan. Design creates the conditions for Arthur to understand and use it.',wayfinding:'Route intelligence can change instantly. The physical environment and human fallback must be able to change with it.',meds:'Finding the discrepancy is a technology function. Resolving, explaining and owning it is an operating design decision.',command:'Visibility does not create capacity. Seeing the problem matters only when the hospital is designed to respond.'}[id]}
function soloActivationImpact(){let c=soloCapability(soloState.pendingCapability),[ca,ch]=soloCost(c.id);soloShell(`<div class="eyebrow">DECISION → IMPACT → AHA</div><h1>YOU INVESTD ${E(c.name.toUpperCase())}.</h1>${storyboardHTML({...soloState,activations:[...soloState.activations,{capabilityId:c.id}]},'capability',asset)}<section class="impact-hero"><b>HERE’S WHAT THAT CHANGES FOR ARTHUR</b><h2>${E(soloFuture[c.id])}</h2></section><div class="impact-grid"><div><b>FOR ARTHUR</b><p>${E(capabilityLong(c)?.arthur||c.purpose)}</p></div><div><b>PEOPLE + OPERATIONS</b><p>${E(capabilityLong(c)?.operations||'Ownership and workflow must now be established.')}</p></div><div><b>BUILT ENVIRONMENT</b><p>${E(capabilityLong(c)?.environment||'The environment must support the experience.')}</p></div><div><b>CAPACITY</b><p>${ca} Capital · ${ch} Change will be committed once you finish designing how this works.</p></div></div><blockquote class="micro-aha"><b>AHA</b><p>${E(capabilityAha(c.id))}</p></blockquote>${soloButton('soloNext','NOW DESIGN AROUND IT',()=>soloSet('commitment'))}`,{complete:true})}
const designChoiceVisuals={
 wayfinding:{digital:'design-app-first.png',layered:'design-layered-guidance.png',human:'design-guided-transition.png'}
};
function plainDesignChoice(capabilityId,x){
 if(capabilityId==='wayfinding'){
  let label=(x.label||'').toLowerCase();
  if(label.includes('digital')&&!label.includes('layer'))return {title:'APP FIRST',line:'Arthur’s wayfinding app provides updated routes.',consideration:'The building may not reinforce the new route.',image:designChoiceVisuals.wayfinding.digital};
  if(label.includes('human')||label.includes('escort'))return {title:'GUIDED TRANSITION',line:'A person guides Arthur through the transition.',consideration:'The route depends on someone being available.',image:designChoiceVisuals.wayfinding.human};
  return {title:'LAYERED GUIDANCE',line:'The app, building and people point Arthur the same way.',consideration:'Digital and physical guidance must stay synchronized.',image:designChoiceVisuals.wayfinding.layered};
 }
 return {title:x.label,line:x.benefit,consideration:x.compromise,image:leaveWellVisuals[capabilityId]};
}
function soloCommitment(){let c=soloCapability(soloState.pendingCapability),views=soloCommitmentOptions(c.id);soloShell(`${soloBars()}${arthurKey(needMap[c.id])}<div class="eyebrow">NOW DESIGN AROUND IT</div><h1>${c.id==='wayfinding'?'HOW SHOULD ARTHUR FIND HIS WAY?':E(soloCommitmentQuestion(c.id))}</h1><p class="solo-lead design-prompt">Choose how this investment becomes part of Arthur’s environment.</p><div class="design-choice-grid">${views.map(x=>{let v=plainDesignChoice(c.id,x);return `<article class="design-choice-card"><img src="${asset(v.image)}" alt="${E(v.title)}"><div class="design-choice-body"><h2>${E(v.title)}</h2><p class="design-choice-line">${E(v.line)}</p>${capabilityNeedTags(c.id)}<div class="design-consideration"><b>DESIGN CONSIDERATION</b><p>${E(v.consideration)}</p></div><button type="button" data-commitment="${E(x.id)}">CHOOSE THIS DESIGN</button></div></article>`}).join('')}</div>`,{decision:true});document.querySelectorAll('[data-commitment]').forEach(b=>b.onclick=()=>soloSaveActivation(c.id,b.dataset.commitment))}

function soloCommitmentImpact(){let a=soloState.activations.at(-1),c=soloCapability(a.capabilityId),x=a.choice;soloShell(`<div class="eyebrow">DECISION → IMPACT → AHA</div><h1>YOU DESIGNED ${E(x.label.toUpperCase())}.</h1>${storyboardHTML(soloState,'design',asset)}<section class="impact-hero"><b>WHAT ARTHUR GAINS</b><h2>${E(x.benefit)}</h2></section><div class="impact-grid"><div><b>THE ENVIRONMENT NOW HAS TO</b><p>${E(soloCommitmentView(c.id,x))}</p></div><div><b>OPERATIONS NOW HAVE TO</b><p>${E(x.compromise)}</p></div><div><b>YOU ACCEPTED</b><p>${E(x.compromise)}</p></div><div><b>REMAINING CAPACITY</b><p>${soloState.capital} Capital · ${soloState.change} Change</p></div></div><blockquote class="micro-aha"><b>AHA</b><p>${E(commitmentAha(c.id,x))}</p></blockquote>${soloButton('soloNext','REVIEW YOUR DESIGN',()=>soloSet('design'))}`,{complete:true})}
function soloOperationsDecision(){let index=soloState.activations.length-1,a=soloState.activations[index],c=soloCapability(a.capabilityId),choices=soloOperations[c.id];soloShell(`<div class="eyebrow">OPERATIONS · YOUR DECISION</div><h1>WHAT HAS TO REMAIN TRUE FOR THIS DESIGN TO WORK?</h1><p class="solo-lead">The capability and experience are defined. Choose the operating commitment that keeps them usable when conditions change.</p><div class="solo-choice-list">${choices.map(o=>`<article class="solo-choice-card"><h2>${E(o.label)}</h2><div class="choice-grid"><p><b>WHAT IT PROTECTS</b><br>${E(o.benefit)}</p><p><b>WHAT YOU ACCEPT</b><br>${E(o.tradeoff)}</p><p><b>DEPENDENCY CREATED</b><br>${E(o.dependency)}</p></div><button type="button" data-operation="${o.id}">COMMIT TO THIS OPERATING MODEL</button></article>`).join('')}</div>`,{decision:true});document.querySelectorAll('[data-operation]').forEach(b=>b.onclick=()=>{let operation=choices.find(o=>o.id===b.dataset.operation);soloState.activations[index]={...a,operation};soloState.pendingOperation=operation.id;saveSolo();soloSet('operations-impact')})}
function soloOperationsImpact(){let a=soloState.activations.at(-1),c=soloCapability(a.capabilityId),o=a.operation;soloShell(`<div class="eyebrow">DECISION → IMPACT → AHA</div><h1>YOU MADE THE DESIGN OPERATIONAL.</h1>${storyboardHTML(soloState,'operations',asset)}<section class="impact-hero"><b>WHAT THIS PROTECTS FOR ARTHUR</b><h2>${E(o.benefit)}</h2></section><div class="impact-grid"><div><b>OPERATING COMMITMENT</b><p>${E(o.label)}</p></div><div><b>TRADEOFF</b><p>${E(o.tradeoff)}</p></div><div><b>DEPENDENCY CREATED</b><p>${E(o.dependency)}</p></div><div><b>CAPABILITY</b><p>${E(c.name)}</p></div></div><blockquote class="micro-aha"><b>AHA</b><p>${E(o.aha)}</p></blockquote>${soloButton('soloNext','SEE YOUR DESIGN SO FAR',()=>soloSet('design'))}`,{complete:true})}
function soloDesign(){let affordable=S().capabilities.some(k=>!soloState.activations.some(i=>i.capabilityId===k.id)&&soloCost(k.id)[0]<=soloState.capital&&soloCost(k.id)[1]<=soloState.change),first=soloState.activations.length===1;soloShell(`${soloBars()}<div class="eyebrow">YOUR ROUND 1 DESIGN</div><h1>DESIGN CAPABILITY + COMMITMENT</h1>${storyboardHTML(soloState,'operations',asset)}<div class="portfolio-summary">${soloState.activations.map(a=>`<article><h2>${E(soloCapability(a.capabilityId).name)}</h2><p><b>DESIGN</b><br>${E(a.choice.label)}</p><p><b>OPERATING COMMITMENT</b><br>${E(a.operation?.description||soloCommitmentView(a.capabilityId,a.choice))}</p><p><b>ARTHUR GAINS</b><br>${E(a.choice.benefit)}</p><p><b>TRADEOFF</b><br>${E(a.choice.compromise)}</p></article>`).join('')}</div><div class="callout">The design capability creates possibility. The built environment and operating commitment make it usable under pressure.</div>${first?`<div class="eyebrow">YOUR SECOND INVESTMENT</div><h2>GO DEEPER OR GO BROADER?</h2><div class="depth-breadth"><article><h3>STRENGTHEN THIS DESIGN</h3><p>Invest 1 Capital + 1 Change to reinforce the design capability, built environment and operating commitment already selected.</p><button type="button" id="soloStrengthen" ${soloState.capital<1||soloState.change<1?'disabled':''}>STRENGTHEN · 1 CAPITAL + 1 CHANGE</button></article><article><h3>EXTEND THE JOURNEY</h3><p>Add another design capability to cover a different Arthur need and accept another design commitment and tradeoff.</p><button type="button" id="soloExtend" ${!affordable?'disabled':''}>EXTEND WITH ANOTHER CAPABILITY</button></article></div>`:`<div class="storyline">TWO CAPABILITIES ACTIVATED · PORTFOLIO COMPLETE</div>`}<div class="solo-actions">${soloButton('soloProceed','PROCEED WITH THIS DESIGN',()=>soloSet('event'))}</div>`,{complete:true});if(q('#soloStrengthen'))q('#soloStrengthen').onclick=()=>{soloState=strengthenCurrent(soloState);saveSolo();soloSet('event')};if(q('#soloExtend'))q('#soloExtend').onclick=()=>{soloState=extendJourney(soloState);saveSolo();soloSet('capability')}}
const severity={ABSORBED:0,STRAINED:1,EXPOSED:2};
function soloActivationEvidence(a){let c=soloCapability(a.capabilityId),x=a.choice;return{capability:c.name,commitment:x.label,outcome:x.outcome||'STRAINED',arthur:x.arthur||x.benefit,held:x.held||x.benefit,gap:x.failed||x.compromise,aha:x.aha||'Technology created possibility. Design shaped the experience.'}}
function soloPortfolioEvaluation(){let evidence=soloState.activations.map(soloActivationEvidence),way=soloState.activations.find(a=>a.capabilityId==='wayfinding'),command=soloState.activations.find(a=>a.capabilityId==='command'),ambient=soloState.activations.find(a=>a.capabilityId==='ambient'),meds=soloState.activations.find(a=>a.capabilityId==='meds'),anchor=way||command||ambient||meds,base=anchor?soloActivationEvidence(anchor):{outcome:'EXPOSED',arthur:'Arthur reaches a changed route without a designed response.',held:'No activation directly supports the disruption.',gap:'The transition depends on improvised help.',aha:'Future-ready intent is not the same as an activated response.'},score=severity[base.outcome]??1;
 let responseEffect=0,responseWhy='';
 if(soloState.response==='route'){if(way){responseEffect=way.commitmentId==='layered'?-1:way.commitmentId==='digital'?0:0;responseWhy=way.commitmentId==='layered'?'The route changes digitally and the designed physical cues reinforce the detour.':'The digital route updates, but the response still depends on the design surrounding the route.'}else{responseEffect=0;responseWhy='No wayfinding capability was activated, so Arthur relies on general hospital directions.'}}
 if(soloState.response==='human'){if(way?.commitmentId==='escort'||command?.commitmentId==='liaison'){responseEffect=-1;responseWhy='The design already created accountable human support for Arthur’s transition.'}else if(command){responseEffect=0;responseWhy='Coordination can find help, but the response still depends on available staffing and authority.'}else{responseEffect=1;responseWhy='Human help was not established as part of the design, so Arthur must wait for improvised support.'}}
 if(soloState.response==='environment'){if(way?.commitmentId==='layered'){responseEffect=-1;responseWhy='Physical cues were already part of the operating design and can be updated for the detour.'}else if(command?.commitmentId==='center'){responseEffect=0;responseWhy='The command center can coordinate an environmental response, but someone still has to update the physical setting.'}else{responseEffect=1;responseWhy='The design did not establish ownership for changing environmental cues when routes change.'}}
 let operationsEffect=soloState.activations.reduce((n,a)=>n+(a.operation?.effect||0),0),finalScore=Math.max(0,Math.min(2,score+responseEffect+operationsEffect)),fourNeedOutcome=outcomeFromFourNeeds(soloState,'MOVE'),outcome=fourNeedOutcome.classification;
 let support=evidence.filter(e=>e.capability!==base.capability).map(e=>`${e.capability}: ${e.arthur}`).join(' ');
 let operations=soloState.activations.map(a=>`${soloCapability(a.capabilityId).name}: ${a.operation?.dependency||'No operating dependency defined.'}`).join(' '); return{outcome,scores:fourNeedOutcome.scores,base,evidence,responseWhy,support,operations,sameTechAha:way?`Adaptive Wayfinding supplied route intelligence. ${way.commitmentId==='layered'?'Layered physical and human reinforcement turned that intelligence into a usable journey.':way.commitmentId==='digital'?'The route was accurate, but the environment and human fallback did not change with it.':'Human support helped interpret the route, but shared staffing introduced delay.'}`:'The activated technology shaped what the hospital could see or coordinate. The experience still depended on authority, workflow, people and place.'}}
function responseAvailability(id){let way=soloState.activations.find(a=>a.capabilityId==='wayfinding'),command=soloState.activations.find(a=>a.capabilityId==='command');if(id==='route')return way?['READY','Your wayfinding design can be used now.']:['LIMITED','No adaptive wayfinding capability was activated.'];if(id==='human')return way?.commitmentId==='escort'||command?.commitmentId==='liaison'?['READY','Your design established accountable human support.']:command?['DELAYED','Coordination may locate help, but staffing was not guaranteed.']:['IMPROVISED','No human fallback was activated.'];if(id==='environment')return way?.commitmentId==='layered'?['READY','Layered physical cues are part of the design.']:command?.commitmentId==='center'?['DELAYED','The response can be coordinated, but physical cues still need an owner.']:['IMPROVISED','Environmental cue updates were not part of the operating design.']}
function soloEvent(){soloShell(`<div class="eyebrow">ARTHUR IS DRESSED. THE RIDE HOME IS WAITING.</div><section class="scene-card"><img src="${asset('arthur-connected-care.png')}" alt="Arthur moving through the hospital as conditions change"><div><h1>THE ELEVATOR ON ARTHUR’S PLANNED DISCHARGE ROUTE GOES OUT OF SERVICE.</h1><p>The technology has not failed. The conditions around Arthur just changed.</p></div></section><p class="solo-lead">Arthur reaches the junction. The phone route has updated. The existing sign still points toward the closed elevator. The nearest staff member is helping another patient.</p><div class="pressure-line">THE TECHNOLOGY HAS NOT FAILED. THE CONDITIONS AROUND ARTHUR JUST CHANGED.</div><h2>Before you respond, what do you expect?</h2><div class="solo-predict"><button data-predict="YES">THE DESIGN WILL HOLD</button><button data-predict="NOT SURE">NOT SURE</button><button data-predict="NO">THE DESIGN WILL NOT HOLD</button></div>`,{decision:true});document.querySelectorAll('[data-predict]').forEach(b=>b.onclick=()=>{soloState.prediction=b.dataset.predict;saveSolo();soloGo('pressure')})}
function soloPressure(){let options=[['route','USE THE DESIGNED ROUTE GUIDANCE','Use the route information and guidance already activated.'],['human','MOBILIZE HUMAN SUPPORT','Get a person to help Arthur interpret and continue the transition.'],['environment','REINFORCE THE ENVIRONMENT','Create or update a physical cue at the changed junction.']];soloShell(`<div class="eyebrow">DESIGN UNDER PRESSURE</div><h1>ARTHUR NEEDS TO KEEP MOVING.</h1><p class="solo-lead">Respond using the people, places and operating capacity your design actually created.</p><div class="pressure-options">${options.map(([id,label,copy])=>{let[a,b]=responseAvailability(id);return`<article><span class="availability ${a.toLowerCase()}">${a}</span><h2>${label}</h2><p>${copy}</p><small>${E(b)}</small><button type="button" data-response="${id}">CHOOSE THIS RESPONSE</button></article>`}).join('')}</div>`,{decision:true});document.querySelectorAll('[data-response]').forEach(b=>b.onclick=()=>{soloState.response=b.dataset.response;saveSolo();soloGo('consequence')})}
function soloConsequence(){let r=soloPortfolioEvaluation(),expected=soloState.prediction==='YES'?'The design would hold':soloState.prediction==='NO'?'The design would not hold':'The result was uncertain';soloShell(`<div class="eyebrow">ARTHUR REACHES THE JUNCTION</div><h1>${E(r.base.arthur)}</h1>${storyboardHTML(soloState,'outcome',asset)}<div class="experience-classification"><span>DESIGN RESPONSE</span><strong>${E(r.outcome)}</strong></div><section class="four-need-score">${Object.entries(r.scores).map(([k,v])=>`<div><b>${k}</b><span>${'●'.repeat(v)}${'○'.repeat(3-v)}</span></div>`).join('')}</section><section class="expected-vs-actual"><div><b>YOU EXPECTED</b><p>${E(expected)}</p></div><div><b>WHAT HAPPENED</b><p>${E(r.outcome)}</p></div></section><section class="response-explanation"><b>WHY YOUR RESPONSE WORKED THIS WAY</b><p>${E(r.responseWhy)}</p></section><section class="portfolio-evidence"><h2>HOW THE PORTFOLIO CONTRIBUTED</h2>${r.evidence.map(e=>`<article><b>${E(e.capability)}</b><span>${E(e.commitment)}</span><p>${E(e.arthur)}</p></article>`).join('')}${r.support?`<p class="support-note">${E(r.support)}</p>`:''}<p class="support-note"><b>OPERATING DEPENDENCIES</b><br>${E(r.operations)}</p></section><blockquote class="aha-block"><b>THE AHA</b><p>${E(r.sameTechAha)}</p><strong>TECHNOLOGY CHANGED WHAT WAS POSSIBLE. DESIGN DETERMINED WHAT ARTHUR COULD ACTUALLY DO.</strong></blockquote><div class="solo-actions">${soloButton('soloTry','TRY ONE DIFFERENT DESIGN',()=>soloStartRevision(),true)}${soloButton('soloNext','WHAT DID WE LEARN?',()=>soloGo('principle'))}</div>`,{complete:true})}
function soloStartRevision(){soloState.comparison={previousOutcome:soloPortfolioEvaluation().outcome,previousResponse:soloState.response};if(soloState.activations.length===1){soloState.reviseIndex=0;saveSolo();soloGo('revise')}else{saveSolo();soloGo('choose-revision')}}
function soloChooseRevision(){soloShell(`<div class="eyebrow">CHANGE ONE VARIABLE</div><h1>WHICH DESIGN WILL YOU REVISIT?</h1><p>Everything else will stay the same so you can see what the design decision changes for Arthur.</p><div class="solo-choice-list">${soloState.activations.map((a,i)=>`<article class="solo-choice-card"><h2>${E(soloCapability(a.capabilityId).name)}</h2><h3>${E(a.choice.label)}</h3><button type="button" data-revise-index="${i}">REVISE THIS DESIGN</button></article>`).join('')}</div>`,{decision:true});document.querySelectorAll('[data-revise-index]').forEach(b=>b.onclick=()=>{soloState.reviseIndex=Number(b.dataset.reviseIndex);saveSolo();soloGo('revise')})}
function soloRevise(){let a=soloState.activations[soloState.reviseIndex],c=soloCapability(a.capabilityId);soloShell(`<div class="eyebrow">SAME ARTHUR · SAME CAPABILITY · SAME DISRUPTION</div><h1>CHANGE ONE DESIGN DECISION.</h1><p>Current design: <b>${E(a.choice.label)}</b></p><div class="solo-choice-list">${c.choices.filter(x=>x.id!==a.commitmentId).map(x=>`<article class="solo-choice-card"><h2>${E(x.label)}</h2><div class="choice-grid"><p><b>WHAT ARTHUR GAINS</b><br>${E(x.benefit)}</p><p><b>WHAT YOU COMMIT TO</b><br>${E(soloCommitmentView(c.id,x))}</p><p><b>WHAT MIGHT BREAK</b><br>${E(x.compromise)}</p></div><button type="button" data-new-design="${x.id}">TRY THIS DESIGN</button></article>`).join('')}</div>`,{decision:true});document.querySelectorAll('[data-new-design]').forEach(b=>b.onclick=()=>{let x=c.choices.find(v=>v.id===b.dataset.newDesign);soloState.activations[soloState.reviseIndex]={...a,commitmentId:x.id,choice:x};soloState.response=null;saveSolo();soloGo('event')})}
function soloPrinciple(){let r=soloPortfolioEvaluation();soloShell(`<div class="eyebrow">FUTURE READINESS BY DESIGN</div><h1>TECHNOLOGY CHANGED WHAT WAS POSSIBLE.<br>DESIGN DETERMINED WHAT ARTHUR COULD ACTUALLY DO.</h1><div class="vitruvian-grid"><article><b>UTILITAS · USEFULNESS</b><h2>Does it work for Arthur?</h2><p>The design supports Arthur’s needs and real journey.</p></article><article><b>FIRMITAS · RESILIENCE</b><h2>Does it hold when conditions change?</h2><p>Technology, place, people and operations adapt together.</p></article><article><b>VENUSTAS · HUMAN EXPERIENCE</b><h2>Does it support dignity, confidence and belonging?</h2><p>Arthur is supported as a person, not processed by a system.</p></article></div><div class="aha-principles"><article><b>TECHNOLOGY CREATES POSSIBILITY.</b><p>AI can detect, route, reconcile and coordinate.</p></article><article><b>DESIGN CREATES USABILITY.</b><p>Place, workflow, ownership and human fallback determine whether Arthur can act on that possibility.</p></article><article><b>ADAPTABILITY MUST BE OPERATIONAL.</b><p>A flexible environment only helps when people can update it, govern it and respond in time.</p></article></div><blockquote class="final-thesis">AI CHANGED WHAT WAS POSSIBLE. DESIGN DETERMINED WHETHER ARTHUR COULD USE IT.</blockquote><div class="storyline">ROUND 1 · LEAVE WELL COMPLETE</div><p>Recover Well and Live Well will carry these activated capabilities, dependencies and tradeoffs into Arthur’s next environments.</p>${soloButton('soloRestartRound','REPLAY LEAVE WELL',()=>soloReset())}`,{complete:true})}
function soloRender(){if(soloState.phase==='operations'||soloState.phase==='operations-impact'){let a=soloState.activations.at(-1);if(a&&!a.operation)a.operation={id:'embedded',label:'Embedded operating commitment',description:soloCommitmentView(a.capabilityId,a.choice),dependency:a.choice.compromise,effect:0};soloState.phase='design';saveSolo()}switch(soloState.phase){case'meet':return soloMeet();case'journey':return soloJourney();case'needs':return soloNeeds();case'rules':return soloRules();case'capability-intro':return soloCapabilityIntro();case'card-guide':return soloCardGuide();case'capability':return soloCapabilities();case'activation-impact':return soloActivationImpact();case'commitment':return soloCommitment();case'commitment-impact':return soloCommitmentImpact();case'design':return soloDesign();case'event':return soloEvent();case'pressure':return soloPressure();case'consequence':return soloConsequence();case'choose-revision':return soloChooseRevision();case'revise':return soloRevise();case'principle':return soloPrinciple();default:soloReset()}}
function solo(){loadSolo();soloRender()}

if(mode==='facilitator')facilitator();else if(mode==='player')player();else if(mode==='solo')solo();else start()
